#include <stdio.h>
#include <dlfcn.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
int main() {
    void* h = dlopen("/lib/x86_64-linux-gnu/libbrotlienc.so.1", RTLD_NOW);
    void* hc = dlopen("/lib/x86_64-linux-gnu/libbrotlicommon.so.1", RTLD_NOW);
    printf("opened\n"); fflush(stdout);
    int (*compress)(int, int, int, size_t, const uint8_t*, size_t*, uint8_t*) = dlsym(h, "BrotliEncoderCompress");
    printf("sym %p\n", (void*)compress); fflush(stdout);
    size_t (*maxsize)(size_t) = dlsym(h, "BrotliEncoderMaxCompressedSize");
    const char* input = "hello world";
    size_t in_size = strlen(input);
    size_t out_size = maxsize(in_size);
    printf("max %zu\n", out_size); fflush(stdout);
    uint8_t* out = malloc(out_size);
    size_t enc_size = out_size;
    int ret = compress(11, 24, 0, in_size, (uint8_t*)input, &enc_size, out);
    printf("ret %d enc_size %zu\n", ret, enc_size); fflush(stdout);
    printf("hex: ");
    for (size_t i=0;i<enc_size;i++) printf("%02x ", out[i]);
    printf("\n"); fflush(stdout);
    // Try quality 0
    enc_size = out_size;
    ret = compress(0, 24, 0, in_size, (uint8_t*)input, &enc_size, out);
    printf("q0 ret %d size %zu hex: ", ret, enc_size);
    for (size_t i=0;i<enc_size;i++) printf("%02x ", out[i]);
    printf("\n");
    // Try empty
    enc_size = out_size;
    // need max for 0
    size_t max0 = maxsize(0);
    uint8_t* out0 = malloc(max0);
    size_t enc0 = max0;
    ret = compress(11, 24, 0, 0, (uint8_t*)"", &enc0, out0);
    printf("empty q11 ret %d size %zu hex: ", ret, enc0);
    for (size_t i=0;i<enc0;i++) printf("%02x ", out0[i]);
    printf("\n");
