// Returns 0 on success, -1 on invalid. Decoded bytes in out (max 80), len in out_len
// Rules: ignore whitespace (space, \t, \n, \r, \v, \f), alphabet A-Za-z0-9 + - / _ and = (padding, only at end, max 2)
// Any other char -> invalid. = in middle -> invalid. === (3+ pads) -> invalid. Decoded len >80 -> invalid.
static int b64_val(char c, int *is_pad) {
    *is_pad = 0;
    if (c >= 'A' && c <= 'Z') return c - 'A';
    if (c >= 'a' && c <= 'z') return c - 'a' + 26;
    if (c >= '0' && c <= '9') return c - '0' + 52;
    if (c == '+' || c == '-') return 62;
    if (c == '/' || c == '_') return 63;
    if (c == '=') { *is_pad = 1; return 0; }
    return -1;
}
static int is_b64_space(char c) {
    return c==' '||c=='\t'||c=='\n'||c=='\r'||c=='\v'||c=='\f';
}
static int decode_comment(const char *s, uint8_t *out, size_t *out_len) {
    // s is guaranteed non-empty (empty already handled as missing param)
    // First, strip whitespace and validate chars, check = placement
    size_t n = strlen(s);
    // Build cleaned string without whitespace
    char *clean = malloc(n+1);
    size_t cn=0;
    size_t i;
    for (i=0;i<n;i++) {
        char c=s[i];
        if (is_b64_space(c)) continue;
        int is_pad=0;
        int v=b64_val(c,&is_pad);
        if (v==-1 && !is_pad) { free(clean); return -1; }
        clean[cn++]=c;
    }
    clean[cn]='\0';
    // Check = placement: all = must be at end, max 2
    // Find first =
    size_t first_eq = cn; // index of first =
    for (i=0;i<cn;i++) if (clean[i]=='=') { first_eq=i; break; }
    if (first_eq < cn) {
        // All after first_eq must be =
        for (i=first_eq;i<cn;i++) if (clean[i]!='=') { free(clean); return -1; }
        size_t pad_count = cn - first_eq;
        if (pad_count > 2) { free(clean); return -1; }
        // Also, if pad_count>0, need to ensure non-pad part doesn't contain = (already) and pad_count is valid?
        // From tests: "=" (1 pad, 0 non-pad) OK, "==" (2 pads) OK, "===" (3) FAIL (already pad>2), "A===" (1 non-pad +3 pads) FAIL (pad>2)
        // "A=" (1+1) OK, "AB=" (2+1) OK, "ABCD==" (4+2) OK, etc. So any pad 1-2 at end is OK regardless of non-pad length?
        // What about "A=B"? Already fails because = not at end (since after first_eq, must be all =, but "A=B" has B after =, so fails). Good.
    }
    // Now decode: remove padding, decode 6-bit groups
    size_t data_len = first_eq; // number of non-pad chars
    // Decode bits
    uint32_t buffer=0;
    int bits=0;
    size_t o=0;
    for (i=0;i<data_len;i++) {
        char c=clean[i];
        int is_pad=0;
        int v=b64_val(c,&is_pad);
        // v is 0-63, is_pad false (since data_len excludes pads)
        buffer = (buffer<<6) | (uint32_t)v;
        bits+=6;
        if (bits>=8) {
            bits-=8;
            uint8_t b = (buffer>>bits)&0xFF;
            if (o>=80) {
                // Check if we exceed 80: need to see if there are more bytes to come?
                // If o==80 and we have another byte, then invalid (>80)
                free(clean);
                return -1;
            }
            out[o++]=b;
        }
    }
    // Leftover bits (<8) are ignored (as per tests: single char gives 0 bytes, etc.)
    free(clean);
    *out_len=o;
    if (o>80) return -1;
    return 0;
}

