    }
}

// Compute auto lgwin for file size: max(10, min(24, floor(log2(size))+1)), size 0 ->10
static int auto_lgwin(long long size) {
    if (size<=0) return 10;
    // floor(log2(size))
    int l=0;
    long long v=size;
    while (v>1) { v>>=1; l++; }
    // l = floor(log2(size))
    int lg = l+1;
    if (lg<10) lg=10;
    if (lg>24) lg=24;
    return lg;
}

// Read entire file into memory. Returns 0 on success, -1 on open error (with errno set), -2 on read error (with errno)
// For directory: open succeeds, read fails with EISDIR -> return -2
// out_data malloced, out_len set. Caller frees.
static int read_file_full(const char *path, uint8_t **out_data, size_t *out_len, int *err_no) {
    int fd = open(path, O_RDONLY);
    if (fd<0) { *err_no=errno; return -1; }
    struct stat st;
    if (fstat(fd,&st)!=0) { *err_no=errno; close(fd); return -1; }
    // Try to read: if directory, read will fail with EISDIR
    // We'll read in chunks
    size_t cap = 8192;
    size_t len=0;
    uint8_t *buf=malloc(cap);
    if (!buf) { close(fd); *err_no=ENOMEM; return -1; }
    while (1) {
        if (len==cap) {
            size_t nc=cap*2;
            uint8_t *nb=realloc(buf,nc);
            if (!nb) { free(buf); close(fd); *err_no=ENOMEM; return -1; }
            buf=nb; cap=nc;
        }
        ssize_t r=read(fd,buf+len,cap-len);
        if (r<0) {
            int e=errno;
            free(buf); close(fd); *err_no=e; return -2;
        }
        if (r==0) break;
        len+=r;
    }
    close(fd);
    *out_data=buf;
    *out_len=len;
    return 0;
}

