                r.out=outbuf;
                r.out_len=out_len;
                pBrotliDecoderDestroyInstance(s);
                return r;
            }
        } else if (res==2) { // NEEDS_MORE_INPUT
            // Decoder needs more input. Since we provided all input (avail_in is remaining), if avail_in==0, it's truncated.
            // If avail_in>0, it shouldn't happen (since we gave all input, decoder should have consumed? Actually NEEDS_MORE_INPUT with avail_in>0 means decoder didn't consume all? Unlikely. We'll treat as continue?
            if (avail_in==0) {
                // Truncated
                snprintf(r.reason,sizeof(r.reason),"truncated input");
                r.result=1;
                r.out=outbuf;
                r.out_len=out_len;
                r.consumed=in_len; // consumed all
                pBrotliDecoderDestroyInstance(s);
                return r;
            } else {
                // Should not happen, but continue? Actually if avail_in>0, decoder still has input but needs more? That suggests it needs more output? No.
                // To avoid infinite loop, treat as error?
                // Let's continue loop (maybe decoder will make progress with more output space?)
                // Check if output buffer full? If avail_out==0, grow.
                if (avail_out==0) {
                    size_t used = next_out - outbuf;
                    size_t nc=cap*2;
                    uint8_t *nb=realloc(outbuf,nc);
                    if (!nb) { free(outbuf); pBrotliDecoderDestroyInstance(s); snprintf(r.reason,sizeof(r.reason),"out of memory"); r.result=-1; return r; }
                    outbuf=nb;
                    next_out=outbuf+used;
                    avail_out=nc-used;
                    cap=nc;
                    continue;
                } else {
                    // No progress? Break as truncated?
                    snprintf(r.reason,sizeof(r.reason),"truncated input");
                    r.result=1;
                    r.out=outbuf;
                    r.out_len=out_len;
                    r.consumed=in_len - avail_in;
                    pBrotliDecoderDestroyInstance(s);
                    return r;
                }
            }
        } else if (res==3) { // NEEDS_MORE_OUTPUT
            // Output buffer full, grow
            size_t used = next_out - outbuf;
            size_t nc=cap*2;
            if (nc<cap+8192) nc=cap+8192;
            uint8_t *nb=realloc(outbuf,nc);
            if (!nb) { free(outbuf); pBrotliDecoderDestroyInstance(s); snprintf(r.reason,sizeof(r.reason),"out of memory"); r.result=-1; return r; }
            outbuf=nb;
            next_out=outbuf+used;
            avail_out=nc-used;
            cap=nc;
            continue;
        } else {
            // Unknown result
            snprintf(r.reason,sizeof(r.reason),"unknown decoder result %d",res);
            r.result=-1;
            r.out=outbuf;
            r.out_len=out_len;
            pBrotliDecoderDestroyInstance(s);
            return r;
        }
    }
}

