                if (c=='h') {
                    print_help(stderr,prog);
                    exit(0);
                } else if (c=='V') {
                    fputs(version_str,stdout);
                    exit(0);
                } else if (c=='c') {
                    if (cfg.stdout_set) error_with_help(prog,"write to standard output already set");
                    cfg.stdout_set=1;
                } else if (c=='d') {
                    if (cfg.mode_set) error_with_help(prog,"command already set when parsing -d");
                    cfg.mode=1; cfg.mode_set=1;
                } else if (c=='t') {
                    if (cfg.mode_set) error_with_help(prog,"command already set when parsing -t");
                    cfg.mode=2; cfg.mode_set=1;
                } else if (c=='f') {
                    if (cfg.force_set) error_with_help(prog,"force output overwrite already set");
                    cfg.force_set=1;
                } else if (c=='v') {
                    if (cfg.verbose_set) error_with_help(prog,"argument --verbose / -v already set");
                    cfg.verbose_set=1;
                } else if (c=='K') {
                    if (cfg.concat_set) error_with_help(prog,"argument -K / --concatenated already set");
                    cfg.concat_set=1;
                } else if (c=='n') {
                    if (cfg.copy_stat_dup) error_with_help(prog,"argument --no-copy-stat / -n already set");
                    cfg.copy_stat_dup=1; cfg.copy_stat_set=1;
                } else if (c=='s') {
                    if (cfg.squash_set) error_with_help(prog,"argument --squash / -s already set");
                    cfg.squash_set=1;
                } else if (c=='j') {
                    if (cfg.keep_rm_set) error_with_help(prog,"argument --rm / -j or --keep / -k already set");
                    cfg.keep_rm_set=1; cfg.keep_rm_val=1;
                } else if (c=='k') {
                    if (cfg.keep_rm_set) error_with_help(prog,"argument --rm / -j or --keep / -k already set");
                    cfg.keep_rm_set=1; cfg.keep_rm_val=0;
                } else if (c=='Z') {
                    if (cfg.quality_set) error_with_help(prog,"quality already set");
                    cfg.quality_set=1; cfg.quality=11;
                } else {
                    char msg[64];
                    snprintf(msg,sizeof(msg),"invalid argument -%c",c);
                    error_with_help(prog,msg);
                }
            }
            continue;
        }
        // Otherwise, it's a file (including "-" which is stdin, and "-..." after --? Already handled --, but "-" alone is file)
        add_file(&cfg, arg);
    }

