def run_in_dir(exe, args, files, stdin_data=None):
    # files: dict path->content (bytes or str) to create in temp dir
    # Returns (rc, stdout, stderr, resulting files dict path->content or None if not exist, plus file stats?)
    d=tempfile.mkdtemp()
    try:
        for path, content in files.items():
            full=os.path.join(d,path)
            os.makedirs(os.path.dirname(full) if os.path.dirname(full) else d, exist_ok=True)
            # Handle directory creation? If content is None and path ends with /? For now, content None means directory?
            if content=="__DIR__":
                os.makedirs(full, exist_ok=True)
            else:
                if isinstance(content,str): content=content.encode()
                open(full,'wb').write(content)
        p=subprocess.run([exe]+args, input=stdin_data, capture_output=True, cwd=d, timeout=5)
        # Collect resulting files: list all files in d recursively
        result={}
        for root,dirs,filenames in os.walk(d):
            for fn in filenames:
                full=os.path.join(root,fn)
                rel=os.path.relpath(full,d)
                # Skip e.txt, o.bin? Actually include all
                try:
                    result[rel]=open(full,'rb').read()
                except: result[rel]=b"<unreadable>"
            for dn in dirs:
                full=os.path.join(root,dn)
                rel=os.path.relpath(full,d)+"/"
                result[rel]="__DIR__"
        # Normalize stderr timing and prog name
        def norm(b):
            b=re.sub(rb'in \d+\.\d+ sec', b'in T sec', b)
            b=re.sub(rb'Usage: \S+ \[OPTION\]', b'Usage: PROG [OPTION]', b)
            return b
        return p.returncode, norm(p.stdout), norm(p.stderr), result
    finally:
        shutil.rmtree(d)

